insert into passages (id, text, difficulty_level, b, active) values
('d50590b7-ecda-4720-ae03-18b9ef4ebed5', 'The phenomenon known as "choice overload" has become a subject of increasing interest among psychologists and economists alike. Contrary to the intuitive assumption that more options invariably lead to better decisions and greater satisfaction, a growing body of research suggests that an excess of choices can produce the opposite effect. In a now-famous study, researchers set up a tasting booth in a grocery store, alternating between offering twenty-four varieties of jam and offering only six. While the larger display attracted more initial interest from shoppers, those who encountered the smaller selection were significantly more likely to make a purchase. The researchers concluded that an overwhelming array of options can induce a kind of decision paralysis, in which consumers become so preoccupied with weighing trade-offs that they postpone or abandon the decision altogether. Moreover, subsequent studies have found that individuals who do manage to choose from an extensive array often report lower satisfaction with their selection than those who chose from a limited set, possibly because they are more prone to second-guessing themselves and imagining superior alternatives they passed over. These findings have practical implications for businesses, which must strike a delicate balance between offering enough variety to satisfy diverse preferences and avoiding an assortment so vast that it discourages customers from committing to a purchase at all.', 4, 1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('a99acbe8-d624-4170-aab4-c2ea84b9755a', 'sentence_completion', 'The senator''s speech was widely criticized for being deliberately ___, avoiding any concrete commitments.', NULL, '[{"id": "a", "text": "vague"}, {"id": "c", "text": "transparent"}, {"id": "b", "text": "forthright"}, {"id": "d", "text": "precise"}]'::jsonb, 0, '{"strategy": "avoiding concrete commitments = נמנע ממחויבויות קונקרטיות. איזו תכונה מתאימה לנאום שנמנע מהתחייבות?", "correct_reason": "vague = מעורפל. נאום שנמנע ממחויבות קונקרטית הוא מעורפל.", "options_analysis": ["נכון! vague = מעורפל — מתאים ל''avoiding concrete commitments''", "transparent = שקוף — הפוך מהימנעות מהתחייבות", "forthright = ישיר וכן — הפוך מהימנעות", "precise = מדויק — הפוך מהימנעות ממחויבות"]}', 1.6, 1.0, 0.25, 4, 'ai', NULL, true),
('48e85832-e452-41d9-bfb8-7053c9517b57', 'sentence_completion', 'Despite overwhelming evidence to the contrary, the executive remained ___ in his belief that the strategy would succeed.', NULL, '[{"id": "c", "text": "flexible"}, {"id": "d", "text": "obstinate"}, {"id": "b", "text": "skeptical"}, {"id": "a", "text": "uncertain"}]'::jsonb, 1, '{"strategy": "despite overwhelming evidence to the contrary = למרות ראיות מכריעות הפוכות. איזו תכונה מתארת התעקשות למרות ראיות?", "correct_reason": "obstinate = עקשן. התעקשות באמונה למרות ראיות סותרות היא עקשנות.", "options_analysis": ["flexible = גמיש — הפוך מהתעקשות", "נכון! obstinate = עקשן — מתאים ל''despite overwhelming evidence''", "skeptical = ספקן — הפוך, הוא לא ספקן אלא בטוח", "uncertain = לא בטוח — הפוך, הוא היה בטוח מאוד"]}', 1.85, 1.0, 0.25, 4, 'ai', NULL, true),
('96034a22-a7c3-4ba3-8d7b-7cc75c11b2cc', 'sentence_completion', 'The committee''s report was so ___ that even experts struggled to follow its dense technical language.', NULL, '[{"id": "a", "text": "concise"}, {"id": "c", "text": "accessible"}, {"id": "d", "text": "convoluted"}, {"id": "b", "text": "simple"}]'::jsonb, 2, '{"strategy": "even experts struggled to follow = אפילו מומחים התקשו לעקוב. איזו תכונה מתארת טקסט קשה למעקב?", "correct_reason": "convoluted = מסובך/מפותל. טקסט שאפילו מומחים מתקשים בו הוא מסובך.", "options_analysis": ["concise = תמציתי — לא מתאים ל''dense technical language''", "accessible = נגיש — הפוך מ''struggled to follow''", "נכון! convoluted = מסובך — מתאים לקושי לעקוב אפילו למומחים", "simple = פשוט — הפוך מקושי המומחים"]}', 1.83, 1.0, 0.25, 4, 'ai', NULL, true),
('37ddeed2-2f1e-48e1-bb6c-1235048adb51', 'sentence_completion', 'The philanthropist''s ___ donations to the hospital transformed it into a leading research center.', NULL, '[{"id": "a", "text": "withheld"}, {"id": "b", "text": "meager"}, {"id": "c", "text": "rare"}, {"id": "d", "text": "substantial"}]'::jsonb, 3, '{"strategy": "transformed it into a leading research center = הפכה אותו למרכז מחקר מוביל. איזו תרומה יכולה לחולל שינוי כזה?", "correct_reason": "substantial = משמעותית. תרומה גדולה יכולה לחולל שינוי כזה.", "options_analysis": ["withheld = שנמנעה — סותר את קיום התרומה", "meager = זעומה — הפוך מיכולת לחולל שינוי כה גדול", "rare = נדירה — לא מתאר גודל תרומה", "נכון! substantial = משמעותית — מתאים ליכולת לחולל שינוי גדול"]}', 1.18, 1.0, 0.25, 4, 'ai', NULL, true),
('f7d8385a-c5f0-4476-b408-188380e5d443', 'sentence_completion', 'The negotiator''s ___ approach eventually won over even the most reluctant participants.', NULL, '[{"id": "b", "text": "diplomatic"}, {"id": "d", "text": "dismissive"}, {"id": "a", "text": "abrasive"}, {"id": "c", "text": "hostile"}]'::jsonb, 0, '{"strategy": "won over even the most reluctant participants = כבש אפילו את המשתתפים החששניים ביותר. איזו גישה משכנעת חששנים?", "correct_reason": "diplomatic = דיפלומטית. גישה דיפלומטית משכנעת גם משתתפים חששניים.", "options_analysis": ["נכון! diplomatic = דיפלומטית — מתאימה ליכולת לשכנע גם חששנים", "dismissive = מזלזלת — הפוך מיכולת לשכנע חששנים", "abrasive = מחוספסת/פוגענית — הפוך מיכולת לשכנע חששנים", "hostile = עוינת — הפוך מיכולת לשכנע"]}', 1.74, 1.0, 0.25, 4, 'ai', NULL, true),
('355b4dad-3ed1-44c9-89ac-20ec3b15ab62', 'sentence_completion', 'The novelist''s prose is known for its ___ detail, painting vivid pictures with every sentence.', NULL, '[{"id": "b", "text": "careless"}, {"id": "d", "text": "meticulous"}, {"id": "a", "text": "scant"}, {"id": "c", "text": "vague"}]'::jsonb, 1, '{"strategy": "painting vivid pictures with every sentence = מצייר תמונות חיות בכל משפט. איזה פירוט יוצר תמונות חיות?", "correct_reason": "meticulous = קפדני/מדוקדק. פירוט קפדני יוצר תמונות חיות.", "options_analysis": ["careless = רשלני — הפוך מיצירת תמונות חיות ומדויקות", "נכון! meticulous = קפדני — מתאים ליצירת תמונות חיות ומפורטות", "scant = דל — הפוך מ''vivid pictures with every sentence''", "vague = מעורפל — הפוך מ''vivid pictures''"]}', 1.77, 1.0, 0.25, 4, 'ai', NULL, true),
('ce9e2076-e458-47ff-8ca5-1f80bd35caa8', 'sentence_completion', 'The board''s decision to ___ the merger came after months of careful deliberation.', NULL, '[{"id": "a", "text": "sabotage"}, {"id": "c", "text": "dismiss"}, {"id": "d", "text": "sanction"}, {"id": "b", "text": "forbid"}]'::jsonb, 2, '{"strategy": "after months of careful deliberation = אחרי חודשי דיון זהיר. איזו החלטה מגיעה אחרי דיון זהיר וארוך על מיזוג?", "correct_reason": "sanction = לאשר. אחרי דיון ארוך, החלטה טבעית היא לאשר.", "options_analysis": ["sabotage = לחבל — לא הגיוני כתוצאה מדיון זהיר ומאושר", "dismiss = לדחות — פחות מתאים, המשפט מרמז על תהליך שהוביל למיזוג", "נכון! sanction = לאשר — מתאים כתוצאה חיובית של דיון ארוך", "forbid = לאסור — פחות מתאים להקשר של מיזוג שאושר בסוף"]}', 1.61, 1.0, 0.25, 4, 'ai', NULL, true),
('5529c25a-7dfb-457a-bf94-632a6cf7d0cb', 'sentence_completion', 'The scandal left the corporation''s reputation ___, taking years to rebuild public trust.', NULL, '[{"id": "a", "text": "enhanced"}, {"id": "d", "text": "secure"}, {"id": "c", "text": "intact"}, {"id": "b", "text": "tarnished"}]'::jsonb, 3, '{"strategy": "taking years to rebuild public trust = לוקח שנים לבנות מחדש אמון. איך נראה מוניטין שדורש שנים לתקן?", "correct_reason": "tarnished = מוכתם/פגום. מוניטין שדורש שנים לתקן הוא פגום.", "options_analysis": ["enhanced = משופר — הפוך מסקנדל", "secure = מאובטח — הפוך ממוניטין שנפגע", "intact = שלם — הפוך מהצורך לבנות מחדש אמון", "נכון! tarnished = פגום — מתאים לצורך בשנים לבניית אמון מחדש"]}', 1.3, 1.0, 0.25, 4, 'ai', NULL, true),
('5b694fae-af39-43be-a7ca-6aa896c50f0e', 'sentence_completion', 'The professor''s lecture was praised for its ___ analysis of a highly complex economic theory.', NULL, '[{"id": "a", "text": "lucid"}, {"id": "b", "text": "incomplete"}, {"id": "c", "text": "confusing"}, {"id": "d", "text": "superficial"}]'::jsonb, 0, '{"strategy": "highly complex economic theory ...praised = תיאוריה מורכבת...שהוללה. איזה ניתוח של תיאוריה מורכבת יזכה לשבחים?", "correct_reason": "lucid = בהיר/צלול. ניתוח בהיר של תיאוריה מורכבת ראוי לשבח.", "options_analysis": ["נכון! lucid = בהיר — מתאים לניתוח משובח של נושא מורכב", "incomplete = לא שלם — לא היה זוכה לשבח כניתוח", "confusing = מבלבל — הפוך משבח", "superficial = שטחי — לא היה זוכה לשבחים על ניתוח תיאוריה מורכבת"]}', 1.83, 1.0, 0.25, 4, 'ai', NULL, true),
('d0825af2-4107-46ae-ab80-d4adbdb8f191', 'sentence_completion', 'The company''s ___ response to the crisis reassured investors and stabilized the stock price.', NULL, '[{"id": "b", "text": "delayed"}, {"id": "c", "text": "swift"}, {"id": "d", "text": "confused"}, {"id": "a", "text": "careless"}]'::jsonb, 1, '{"strategy": "reassured investors and stabilized = הרגיעה משקיעים וייצבה. איזו תגובה למשבר מרגיעה משקיעים?", "correct_reason": "swift = מהירה. תגובה מהירה למשבר מרגיעה משקיעים.", "options_analysis": ["delayed = מאוחרת — הפוך מיכולת להרגיע ולייצב מהר", "נכון! swift = מהירה — מתאימה לתגובה שמרגיעה ומייצבת", "confused = מבולבלת — הפוך מיכולת לייצב", "careless = חסרת זהירות — הפוך מיכולת להרגיע משקיעים"]}', 1.23, 1.0, 0.25, 4, 'ai', NULL, true),
('1b781b7c-9111-4912-8e08-924a4f8f1f71', 'sentence_completion', 'The historian''s account of the war was notably ___, avoiding the bias present in earlier versions.', NULL, '[{"id": "b", "text": "exaggerated"}, {"id": "c", "text": "partisan"}, {"id": "d", "text": "impartial"}, {"id": "a", "text": "distorted"}]'::jsonb, 2, '{"strategy": "avoiding the bias present in earlier versions = נמנע מהטיה שהייתה בגרסאות קודמות. איזה תיאור נמנע מהטיה?", "correct_reason": "impartial = חסר פניות. תיאור שנמנע מהטיה הוא חסר פניות.", "options_analysis": ["exaggerated = מוגזם — לא מתאר הימנעות מהטיה", "partisan = מוטה/חד-צדדי — הפוך מ''avoiding the bias''", "נכון! impartial = חסר פניות — מתאים ל''avoiding the bias''", "distorted = מעוות — הפוך מהימנעות מהטיה"]}', 1.56, 1.0, 0.25, 4, 'ai', NULL, true),
('be344c84-28a4-4f1f-a773-7ad8a8e72790', 'sentence_completion', 'The startup''s growth was ___ by a sudden influx of venture capital funding.', NULL, '[{"id": "c", "text": "reversed"}, {"id": "d", "text": "halted"}, {"id": "b", "text": "hindered"}, {"id": "a", "text": "accelerated"}]'::jsonb, 3, '{"strategy": "sudden influx of venture capital funding = זרם פתאומי של מימון הון סיכון. מה קורה לצמיחה כשמקבלים הרבה מימון?", "correct_reason": "accelerated = הואצה. מימון גדול פתאומי מאיץ צמיחה.", "options_analysis": ["reversed = התהפכה — לא הגיוני עם מימון נוסף", "halted = נעצרה — הפוך מהשפעת מימון", "hindered = הופרעה — הפוך מהשפעת מימון גדול", "נכון! accelerated = הואצה — תוצאה טבעית של מימון פתאומי גדול"]}', 1.87, 1.0, 0.25, 4, 'ai', NULL, true),
('df191b54-1759-4d7a-826a-e0f21566bd4d', 'restatement', 'The CEO''s resignation, though unexpected, was not entirely surprising given the company''s recent turmoil.', NULL, '[{"id": "c", "text": "Although the CEO''s resignation was unexpected, it was somewhat understandable considering the recent turmoil."}, {"id": "b", "text": "No one anticipated the CEO''s resignation given the company''s stability."}, {"id": "d", "text": "The company experienced no turmoil before the CEO resigned."}, {"id": "a", "text": "The CEO''s resignation was completely predictable months in advance."}]'::jsonb, 0, '{"strategy": "though unexpected...not entirely surprising given turmoil = ניגוד עדין: לא צפוי אך מובן בהתחשב במצב.", "correct_reason": "אותה משמעות מדויקת של הניגוד העדין.", "options_analysis": ["נכון! אותה משמעות מדויקת: לא צפוי אך מובן בהתחשב בתהפוכות", "סותר ''unexpected'' ואת קיום התהפוכות", "סותר את קיום ''recent turmoil''", "סותר ''unexpected'' — לא היה צפוי מראש"]}', 1.49, 1.0, 0.25, 4, 'ai', NULL, true),
('c5fe63e8-1539-45df-83bd-59b81d455aa7', 'restatement', 'The proposal, while ambitious, failed to account for the practical constraints of the budget.', NULL, '[{"id": "a", "text": "The proposal was modest and fully accounted for budget constraints."}, {"id": "c", "text": "The proposal was ambitious but did not consider the budget''s practical limitations."}, {"id": "b", "text": "The budget had no constraints that affected the proposal."}, {"id": "d", "text": "The proposal succeeded because it accounted for every practical constraint."}]'::jsonb, 1, '{"strategy": "while ambitious, failed to account for = למרות שאפתני, לא לקח בחשבון. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — ''modest'' סותר ''ambitious'', וגם סותר ''failed to account''", "נכון! אותה משמעות מדויקת: אפתני אך לא לקח בחשבון מגבלות תקציב", "סותר את קיום מגבלות התקציב", "הפוך גמור — ההצעה נכשלה, לא הצליחה"]}', 1.38, 1.0, 0.25, 4, 'ai', NULL, true),
('d6cbb8c1-71cf-41b0-9cc9-8a1b02099e65', 'restatement', 'Critics argue that the policy, however well-intentioned, ultimately exacerbated the very problem it sought to solve.', NULL, '[{"id": "d", "text": "The policy had no relation to the problem it addressed."}, {"id": "b", "text": "Critics believe the policy successfully solved the problem it addressed."}, {"id": "a", "text": "Critics claim that despite good intentions, the policy made the problem it aimed to fix worse."}, {"id": "c", "text": "Everyone agreed the policy was poorly intentioned from the start."}]'::jsonb, 2, '{"strategy": "however well-intentioned, exacerbated = למרות כוונות טובות, החמיר. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר ''the very problem it sought to solve''", "הפוך — ''successfully solved'' סותר ''exacerbated''", "נכון! אותה משמעות מדויקת: למרות כוונות טובות, החמיר את הבעיה", "סותר ''well-intentioned'' — הכוונות היו טובות"]}', 1.63, 1.0, 0.25, 4, 'ai', NULL, true),
('d5f88ea8-6c6d-491b-9003-76cb6ae2f750', 'restatement', 'The research, though limited in scope, offers valuable preliminary insights into the disease''s progression.', NULL, '[{"id": "d", "text": "The research offers no insights into the disease despite its broad scope."}, {"id": "a", "text": "The disease''s progression was already fully understood before the research."}, {"id": "c", "text": "The research was extensive and provided no useful information."}, {"id": "b", "text": "Despite its narrow scope, the research provides useful early findings about how the disease progresses."}]'::jsonb, 3, '{"strategy": "though limited in scope, offers valuable insights = למרות היקף מוגבל, מציע תובנות חשובות. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''offers valuable preliminary insights''", "סותר ''preliminary'' — המחקר הוא ראשוני, לא סופי", "הפוך — ''extensive'' סותר ''limited in scope''", "נכון! אותה משמעות מדויקת: היקף מצומצם אך תובנות ראשוניות מועילות"]}', 1.81, 1.0, 0.25, 4, 'ai', NULL, true),
('ff2141f8-82e6-45f1-a8a6-75bcb27c14f9', 'restatement', 'The city''s infrastructure, long neglected, is now undergoing a much-needed overhaul.', NULL, '[{"id": "a", "text": "After years of neglect, the city''s infrastructure is finally being significantly renovated."}, {"id": "b", "text": "The city''s infrastructure will never be repaired."}, {"id": "d", "text": "The city''s infrastructure has always received excellent maintenance."}, {"id": "c", "text": "The overhaul of the infrastructure was completed decades ago."}]'::jsonb, 0, '{"strategy": "long neglected...much-needed overhaul = מוזנח זמן רב...שיפוץ נחוץ מאוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: אחרי הזנחה, עובר שיפוץ משמעותי נחוץ", "הפוך — ''now undergoing'' סותר ''never be repaired''", "הפוך — ''excellent maintenance'' סותר ''long neglected''", "סותר ''is now undergoing'' — זה קורה עכשיו, לא הושלם בעבר"]}', 1.42, 1.0, 0.25, 4, 'ai', NULL, true),
('33ec5f33-f857-4dc8-b5e8-84c0a73c8c4c', 'restatement', 'Although the evidence was largely circumstantial, the jury found it compelling enough to convict.', NULL, '[{"id": "a", "text": "The jury refused to consider any of the circumstantial evidence."}, {"id": "d", "text": "Despite the evidence being mostly circumstantial, the jury was convinced enough to find the defendant guilty."}, {"id": "c", "text": "The jury acquitted the defendant due to lack of evidence."}, {"id": "b", "text": "The evidence was direct and conclusive, leaving no room for doubt."}]'::jsonb, 1, '{"strategy": "although circumstantial, compelling enough to convict = למרות היות נסיבתי, שכנע מספיק להרשעה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר ''found it compelling'' — הם כן שקלו את הראיות", "נכון! אותה משמעות מדויקת: למרות ראיות נסיבתיות, שכנעו מספיק להרשעה", "הפוך — ''acquitted'' סותר ''convict''", "סותר ''largely circumstantial''"]}', 1.59, 1.0, 0.25, 4, 'ai', NULL, true),
('6d7747cb-bd28-4763-a986-730eddc8ba30', 'restatement', 'The author''s latest novel, unlike her previous works, received mixed reviews from critics.', NULL, '[{"id": "b", "text": "The author has never written a novel before this one."}, {"id": "c", "text": "The author''s latest novel received the same praise as her previous works."}, {"id": "a", "text": "In contrast to her earlier books, the author''s newest novel got a mix of positive and negative reviews."}, {"id": "d", "text": "Critics unanimously praised the author''s latest novel."}]'::jsonb, 2, '{"strategy": "unlike previous works, mixed reviews = בניגוד ליצירות קודמות, ביקורות מעורבות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר ''previous works'' — יש לה יצירות קודמות", "הפוך — ''same praise'' סותר ''unlike her previous works''", "נכון! אותה משמעות מדויקת: בניגוד לספרים קודמים, ביקורות מעורבות", "הפוך — ''unanimously praised'' סותר ''mixed reviews''"]}', 1.12, 1.0, 0.25, 4, 'ai', NULL, true),
('bea05d8d-1976-4059-af71-02f2094ed7a9', 'restatement', 'The treaty, though initially controversial, has come to be regarded as a diplomatic triumph.', NULL, '[{"id": "d", "text": "The treaty was never controversial and was immediately celebrated."}, {"id": "b", "text": "No one has ever discussed the treaty''s outcome."}, {"id": "a", "text": "The treaty is still considered a failure by most observers."}, {"id": "c", "text": "Although the treaty was controversial at first, it is now seen as a major diplomatic success."}]'::jsonb, 3, '{"strategy": "though initially controversial, now regarded as triumph = ניגוד בין עבר להווה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''initially controversial''", "סותר את קיום דיון על ההסכם", "הפוך — ''failure'' סותר ''diplomatic triumph''", "נכון! אותה משמעות מדויקת: שנוי במחלוקת בתחילה, כעת נחשב הצלחה דיפלומטית"]}', 1.26, 1.0, 0.25, 4, 'ai', NULL, true),
('1eda24d5-471d-40cf-b6cd-d21b2fc20cc6', 'restatement', 'The factory''s emissions, once a major environmental concern, have been reduced dramatically after new regulations took effect.', NULL, '[{"id": "b", "text": "After new regulations were enforced, the factory''s emissions, which had been a serious environmental issue, dropped sharply."}, {"id": "d", "text": "No regulations have ever affected the factory''s emissions."}, {"id": "a", "text": "The factory has never produced any emissions."}, {"id": "c", "text": "The factory''s emissions increased significantly after new regulations were introduced."}]'::jsonb, 0, '{"strategy": "once major concern, reduced dramatically after regulations = ירידה דרסטית בעקבות תקנות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: לאחר אכיפת תקנות, פליטות ירדו בחדות", "סותר את קיום התקנות והשפעתן", "סותר את קיום הפליטות כבעיה סביבתית", "הפוך — ''increased'' סותר ''reduced dramatically''"]}', 1.29, 1.0, 0.25, 4, 'ai', NULL, true),
('8d262ed1-6c6d-4b36-b35a-efc028218ec8', 'restatement', 'The candidate''s platform, while popular among younger voters, struggled to gain traction with older demographics.', NULL, '[{"id": "c", "text": "The candidate''s platform was equally popular across all age groups."}, {"id": "b", "text": "Although popular with younger voters, the candidate''s platform had difficulty appealing to older voters."}, {"id": "a", "text": "Older voters were the primary supporters of the candidate''s platform."}, {"id": "d", "text": "The candidate''s platform failed to attract any voters at all."}]'::jsonb, 1, '{"strategy": "while popular with younger, struggled with older = ניגוד בין קבוצות גיל.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר את ההבדל בין קבוצות הגיל", "נכון! אותה משמעות מדויקת: פופולרי אצל צעירים, קשה למשוך מבוגרים", "הפוך — סותר ''struggled to gain traction with older demographics''", "הפוך — ''popular among younger voters'' סותר כישלון מוחלט"]}', 1.66, 1.0, 0.25, 4, 'ai', NULL, true),
('2c3bf94f-eafc-4341-b550-b5907e8e17a7', 'restatement', 'The team''s performance, despite a promising start, deteriorated significantly in the second half of the season.', NULL, '[{"id": "d", "text": "The team''s performance improved steadily throughout the entire season."}, {"id": "a", "text": "The team''s performance remained consistent throughout the season."}, {"id": "c", "text": "Although the team started promisingly, its performance declined considerably in the season''s second half."}, {"id": "b", "text": "The team performed poorly from the very beginning of the season."}]'::jsonb, 2, '{"strategy": "despite promising start, deteriorated = ניגוד בין התחלה טובה לסוף גרוע.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — ''improved steadily'' סותר ''deteriorated significantly''", "הפוך — ''remained consistent'' סותר ''deteriorated significantly''", "נכון! אותה משמעות מדויקת: התחלה מבטיחה, ירידה משמעותית במחצית השנייה", "סותר ''a promising start'' — ההתחלה כן הייתה טובה"]}', 1.55, 1.0, 0.25, 4, 'ai', NULL, true),
('e0f2cd83-7ca9-40ab-aa42-b5128acaa29d', 'restatement', 'The manuscript, rejected by numerous publishers, eventually became a bestseller after one small press took a chance on it.', NULL, '[{"id": "a", "text": "The manuscript was immediately accepted by every publisher it was sent to."}, {"id": "c", "text": "The manuscript was never published by any press."}, {"id": "b", "text": "The small press regretted publishing the manuscript."}, {"id": "d", "text": "After being turned down by many publishers, the manuscript went on to become a bestseller once a small press published it."}]'::jsonb, 3, '{"strategy": "rejected by many...eventually bestseller = ניגוד בין דחייה להצלחה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''rejected by numerous publishers''", "סותר ''took a chance on it'' — כן פורסם", "הפוך — סותר את ההצלחה כרב מכר", "נכון! אותה משמעות מדויקת: נדחה רבות, הפך לרב-מכר אחרי הוצאה קטנה"]}', 1.38, 1.0, 0.25, 4, 'ai', NULL, true),
('d5ed9417-fb4b-4a8d-9d39-07027cf0b4bd', 'reading_comprehension', 'What is the main idea of the passage?', 'd50590b7-ecda-4720-ae03-18b9ef4ebed5', '[{"id": "a", "text": "An excessive number of choices can paradoxically reduce decision-making and satisfaction"}, {"id": "c", "text": "Psychologists have no interest in studying consumer behavior"}, {"id": "b", "text": "Grocery stores should always offer as many product varieties as possible"}, {"id": "d", "text": "Having more choices always leads to greater customer satisfaction"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה עוסקת בפרדוקס של עודף בחירה.", "correct_reason": "כל הפסקה בונה טיעון סביב ''choice overload'' וההשפעה השלילית שלו על החלטה וסיפוק.", "options_analysis": ["נכון! הפרדוקס של עודף בחירה = הרעיון המרכזי", "סותר את כל הפסקה שמתארת מחקר פסיכולוגי-כלכלי נרחב", "הפוך ממסקנת הפסקה — עודף מגוון עלול להזיק למכירות", "הפוך — הפסקה טוענת בדיוק ההפך"]}', 1.31, 1.0, 0.25, 4, 'ai', NULL, true),
('f2e3e3ae-5327-44e7-b390-ad4d7c423fe8', 'reading_comprehension', 'According to the passage, what happened in the jam-tasting study when shoppers were offered 24 varieties versus 6?', 'd50590b7-ecda-4720-ae03-18b9ef4ebed5', '[{"id": "a", "text": "More shoppers purchased jam from the 24-variety display"}, {"id": "d", "text": "The smaller, 6-variety display resulted in significantly more purchases"}, {"id": "b", "text": "There was no difference in purchasing behavior between the two displays"}, {"id": "c", "text": "Shoppers ignored the 24-variety display entirely"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את תוצאת ניסוי הריבה בפסקה.", "correct_reason": "הפסקה אומרת: ''those who encountered the smaller selection were significantly more likely to make a purchase''.", "options_analysis": ["הפוך גמור מתוצאת המחקר שתוארה בפסקה", "נכון! נאמר במפורש בפסקה", "סותר את המסקנה המפורשת של המחקר", "סותר ''attracted more initial interest'' — היה עניין רב, לא התעלמות"]}', 1.25, 1.0, 0.25, 4, 'ai', NULL, true),
('10050dd0-5bf8-4fb3-8ecc-2c48e86f0a58', 'reading_comprehension', 'The word "induce" in the passage most closely means:', 'd50590b7-ecda-4720-ae03-18b9ef4ebed5', '[{"id": "c", "text": "to prevent"}, {"id": "a", "text": "to postpone indefinitely"}, {"id": "b", "text": "to cause or bring about"}, {"id": "d", "text": "to eliminate"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''can induce a kind of decision paralysis''.", "correct_reason": "induce = לגרום/להביא לידי.", "options_analysis": ["הפוך גמור למשמעות המילה", "לא מדויק — ''induce'' הוא גרימה, לא דחייה בזמן", "נכון! induce = לגרום/להביא לידי", "לא מדויק למשמעות המילה"]}', 1.36, 1.0, 0.25, 4, 'ai', NULL, true),
('38787f1b-a400-4953-8ebe-9ee84acfe939', 'reading_comprehension', 'According to the passage, why do people who choose from a large selection often report lower satisfaction?', 'd50590b7-ecda-4720-ae03-18b9ef4ebed5', '[{"id": "b", "text": "They always regret buying anything at all"}, {"id": "c", "text": "They are unaware that they made a choice at all"}, {"id": "a", "text": "They receive lower-quality products from larger selections"}, {"id": "d", "text": "They are more likely to imagine better alternatives they did not choose"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את ההסבר לסיפוק נמוך יותר בפסקה.", "correct_reason": "הפסקה אומרת: ''...possibly because they are more prone to second-guessing themselves and imagining superior alternatives they passed over''.", "options_analysis": ["לא נאמר בפסקה — אין טענה כזו", "סותר את כל הדיון על תהליך הבחירה שלהם", "לא נאמר בפסקה — אין קשר לאיכות המוצר", "נכון! נאמר במפורש בפסקה"]}', 1.6, 1.0, 0.25, 4, 'ai', NULL, true),
('fdcbcd16-74eb-47d2-92ef-ef20c69b9909', 'reading_comprehension', 'What practical implication does the passage suggest for businesses?', 'd50590b7-ecda-4720-ae03-18b9ef4ebed5', '[{"id": "a", "text": "They must balance offering variety with avoiding overwhelming customers"}, {"id": "b", "text": "They should eliminate all product variety to maximize sales"}, {"id": "d", "text": "They should ignore psychological research when making business decisions"}, {"id": "c", "text": "They should offer unlimited choices regardless of consumer behavior"}]'::jsonb, 0, '{"strategy": "שאלת פרט/מסקנה — חפש את המשפט האחרון בפסקה.", "correct_reason": "הפסקה אומרת: ''must strike a delicate balance between offering enough variety...and avoiding an assortment so vast that it discourages customers''.", "options_analysis": ["נכון! נאמר במפורש בפסקה כאיזון עדין", "קיצוני מדי ולא נאמר בפסקה — לא לבטל מגוון לחלוטין", "הפוך — הפסקה כולה מבוססת על ממצאי מחקר פסיכולוגי", "הפוך גמור ממסקנת הפסקה"]}', 1.51, 1.0, 0.25, 4, 'ai', NULL, true);